import {
    BooleanColumn,
    FieldListColumn,
    GenericColumn,
    ReferenceColumn,
    ScriptColumn,
    StringColumn,
    Table,
    TableNameColumn,
    UserRolesColumn,
} from '../../db'

export const sp_widget = Table({
    name: 'sp_widget',
    extends: 'sys_metadata',
    schema: {
        category: StringColumn({
            label: 'Category',
            dropdown: 'dropdown_without_none',
            choices: {
                standard: { label: 'Standard', sequence: 1 },
                custom: { label: 'Custom', sequence: 2 },
                kb: { label: 'Knowledge Base', sequence: 3 },
                sc: { label: 'Service Catalog', sequence: 4 },
                other: { label: 'Other Applications', sequence: 5 },
                sample: { label: 'Sample', sequence: 6 },
                sp_platform: { label: 'Service Portal Platform', sequence: 7 },
            },
        }),
        client_script: ScriptColumn({
            label: 'Client controller',
            default: `api.controller=function() {  /* widget controller */  var c = this;};`,
        }),
        controller_as: StringColumn({ default: 'c' }),
        css: GenericColumn({
            label: 'CSS',
            column_type: 'css',
        }),
        data_table: TableNameColumn({
            mandatory: true,
            label: 'Data table',
            default: 'sp_instance',
        }),
        description: StringColumn({
            label: 'Description',
        }),
        docs: ReferenceColumn({
            label: 'Docs',
            referenceTable: 'sp_documentation',
        }),
        field_list: FieldListColumn({ label: 'Fields', dependent: 'data_table' }),
        has_preview: BooleanColumn({ label: 'Has preview', default: false }),
        id: StringColumn({ label: 'ID' }),
        internal: BooleanColumn({ label: 'Internal', default: false }),
        link: ScriptColumn({ label: 'Link', default: `function link(scope, element, attrs, controller) {  }` }),
        name: StringColumn({ label: 'Name', mandatory: true }),
        option_schema: GenericColumn({ label: 'Option schema', column_type: 'json' }),
        public: BooleanColumn({ label: 'Public', default: false }),
        roles: UserRolesColumn({ label: 'Roles' }),
        script: ScriptColumn({
            label: 'Server script',
            default: `(function() {
    /* populate the 'data' object */  
    /* e.g., data.table = $sp.getValue('table'); */
})();
`,
        }),
        servicenow: BooleanColumn({ default: false }),
        template: GenericColumn({ column_type: 'html_template', default: `<div><!-- your widget template --></div>` }),
    },
})
